        let name = filename.into().unwrap_or_else(|| File::filename(&path));
        let ext = File::ext(&path);

        let is_all_all = false;
        let recursive_size = if total_size {
            RecursiveSize::Unknown
        } else {
            RecursiveSize::None
        };

