        let filetype = match filetype {
            Some(f) => OnceLock::from(Some(f)),
            None => OnceLock::new(),
        };

        debug!("deref_links {deref_links}");

        let mut file = File {
            name,
            ext,
            path,
            parent_dir,
            is_all_all,
            deref_links,
            recursive_size,
            filetype,
            metadata: OnceLock::new(),
            extended_attributes: OnceLock::new(),
            absolute_path: OnceLock::new(),
